[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Impact on the Global Job Market: Risk, Salary &amp; Skills Trend Analysis (2015–2035)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a2744;
    --accent: #2563eb;
    --accent2: #0ea5e9;
    --danger: #dc2626;
    --warning: #d97706;
    --success: #16a34a;
    --neutral: #64748b;
    --bg: #f8fafc;
    --card: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --muted: #64748b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }

  /* ── Header ── */
  .report-header {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 60%, #1a2744 100%);
    color: #fff; padding: 56px 48px 48px; position: relative; overflow: hidden;
  }
  .report-header::before {
    content: ''; position: absolute; inset: 0;
    background: radial-gradient(ellipse 80% 60% at 70% 50%, rgba(37,99,235,.25) 0%, transparent 70%);
  }
  .report-header .inner { position: relative; max-width: 1100px; margin: 0 auto; }
  .report-label { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: #7dd3fc; margin-bottom: 14px; font-weight: 600; }
  .report-title { font-size: 34px; font-weight: 800; line-height: 1.2; margin-bottom: 16px; }
  .report-subtitle { font-size: 15px; color: #cbd5e1; max-width: 700px; }
  .report-meta { margin-top: 28px; display: flex; gap: 32px; flex-wrap: wrap; }
  .meta-item { font-size: 12px; color: #94a3b8; }
  .meta-item strong { color: #e2e8f0; font-weight: 600; display: block; font-size: 14px; }

  /* ── Nav ── */
  .toc-bar {
    background: var(--primary); color: #e2e8f0; padding: 0 48px;
    position: sticky; top: 0; z-index: 100; border-bottom: 1px solid rgba(255,255,255,.1);
  }
  .toc-bar ul { list-style: none; display: flex; gap: 0; max-width: 1100px; margin: 0 auto; overflow-x: auto; }
  .toc-bar ul::-webkit-scrollbar { display: none; }
  .toc-bar a { display: block; padding: 14px 16px; font-size: 12px; font-weight: 600; color: #94a3b8; text-decoration: none; white-space: nowrap; letter-spacing: .5px; transition: color .2s, border-color .2s; border-bottom: 3px solid transparent; }
  .toc-bar a:hover { color: #fff; border-color: var(--accent2); }

  /* ── Layout ── */
  .container { max-width: 1100px; margin: 0 auto; padding: 0 48px; }
  .section { padding: 56px 0 40px; border-bottom: 1px solid var(--border); }
  .section:last-of-type { border-bottom: none; }
  .section-label { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: var(--accent); font-weight: 700; margin-bottom: 8px; }
  .section-title { font-size: 26px; font-weight: 800; color: var(--primary); margin-bottom: 12px; }
  .section-intro { font-size: 15px; color: var(--muted); max-width: 760px; margin-bottom: 32px; line-height: 1.7; }

  /* ── KPI Cards ── */
  .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 36px; }
  .kpi-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }
  .kpi-card.danger::before { background: var(--danger); }
  .kpi-card.success::before { background: var(--success); }
  .kpi-card.warning::before { background: var(--warning); }
  .kpi-card.neutral::before { background: var(--neutral); }
  .kpi-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); font-weight: 600; margin-bottom: 8px; }
  .kpi-value { font-size: 30px; font-weight: 800; color: var(--primary); line-height: 1; }
  .kpi-sub { font-size: 12px; color: var(--muted); margin-top: 6px; }
  .kpi-trend { font-size: 12px; font-weight: 700; margin-top: 4px; }
  .kpi-trend.up { color: var(--success); }
  .kpi-trend.down { color: var(--danger); }

  /* ── Callout boxes ── */
  .callout { border-left: 4px solid var(--accent); background: #eff6ff; padding: 16px 20px; border-radius: 0 8px 8px 0; margin: 20px 0; font-size: 14px; color: #1e40af; }
  .callout.danger { border-color: var(--danger); background: #fef2f2; color: #991b1b; }
  .callout.success { border-color: var(--success); background: #f0fdf4; color: #166534; }
  .callout.warning { border-color: var(--warning); background: #fffbeb; color: #92400e; }
  .callout strong { display: block; margin-bottom: 4px; font-weight: 700; }

  /* ── Charts ── */
  .chart-grid { display: grid; gap: 24px; margin: 24px 0; }
  .chart-grid.cols-2 { grid-template-columns: repeat(auto-fit, minmax(440px, 1fr)); }
  .chart-grid.cols-3 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
  .chart-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 24px; }
  .chart-title { font-size: 13px; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
  .chart-sub { font-size: 11px; color: var(--muted); margin-bottom: 18px; }
  .chart-wrap { position: relative; height: 280px; }
  .chart-wrap.tall { height: 340px; }
  .chart-wrap.short { height: 220px; }

  /* ── Tables ── */
  .table-wrap { overflow-x: auto; margin: 20px 0; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th { background: var(--primary); color: #fff; padding: 10px 14px; text-align: left; font-weight: 600; font-size: 11px; letter-spacing: .5px; text-transform: uppercase; }
  th:first-child { border-radius: 8px 0 0 0; }
  th:last-child { border-radius: 0 8px 0 0; }
  td { padding: 10px 14px; border-bottom: 1px solid var(--border); }
  tr:nth-child(even) td { background: #f8fafc; }
  tr:hover td { background: #eff6ff; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 99px; font-size: 11px; font-weight: 700; }
  .badge-danger { background: #fee2e2; color: #b91c1c; }
  .badge-warning { background: #fef3c7; color: #b45309; }
  .badge-success { background: #dcfce7; color: #15803d; }
  .badge-neutral { background: #f1f5f9; color: #475569; }
  .risk-bar { display: inline-block; height: 6px; border-radius: 3px; vertical-align: middle; margin-right: 6px; }

  /* ── Recommendations ── */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 20px; margin: 24px 0; }
  .rec-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 24px; }
  .rec-num { width: 32px; height: 32px; border-radius: 50%; background: var(--accent); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 14px; margin-bottom: 12px; }
  .rec-title { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 8px; }
  .rec-body { font-size: 13px; color: var(--muted); line-height: 1.6; }
  .rec-evidence { font-size: 11px; color: var(--accent); margin-top: 10px; font-weight: 600; border-top: 1px solid var(--border); padding-top: 10px; }

  /* ── Executive summary bullets ── */
  .exec-findings { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 16px; margin: 24px 0; }
  .exec-finding { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 18px 20px; display: flex; gap: 14px; align-items: flex-start; }
  .exec-icon { font-size: 22px; flex-shrink: 0; margin-top: 2px; }
  .exec-finding-title { font-size: 13px; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
  .exec-finding-body { font-size: 12px; color: var(--muted); line-height: 1.5; }

  /* ── Footer ── */
  .report-footer { background: var(--primary); color: #94a3b8; padding: 32px 48px; margin-top: 40px; }
  .report-footer .inner { max-width: 1100px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; flex-wrap: gap; font-size: 12px; }
  .report-footer strong { color: #e2e8f0; }

  @media (max-width: 700px) {
    .report-header { padding: 36px 20px; }
    .container { padding: 0 20px; }
    .report-title { font-size: 24px; }
    .chart-grid.cols-2 { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- ══════════════════════════════════════════════════
     HEADER
═══════════════════════════════════════════════════ -->
<div class="report-header">
  <div class="inner">
    <div class="report-label">Trend Analysis Report &nbsp;·&nbsp; Executive Edition</div>
    <h1 class="report-title">AI Impact on the Global Job Market:<br>Risk, Salary &amp; Skills (2015–2035)</h1>
    <p class="report-subtitle">A comprehensive analysis of how AI automation is reshaping employment, compensation, and skill demand across 10 job categories, 6 countries, and three experience tiers over a 21-year horizon.</p>
    <div class="report-meta">
      <div class="meta-item"><strong>12,343</strong> Records Analyzed</div>
      <div class="meta-item"><strong>2015 – 2035</strong> Time Horizon</div>
      <div class="meta-item"><strong>10</strong> Job Categories</div>
      <div class="meta-item"><strong>6</strong> Countries</div>
      <div class="meta-item"><strong>Published</strong> April 2026</div>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════════
     NAVIGATION
═══════════════════════════════════════════════════ -->
<nav class="toc-bar">
  <ul>
    <li><a href="#executive-overview">Executive Overview</a></li>
    <li><a href="#automation-risk">Automation Risk</a></li>
    <li><a href="#salary-trends">Salary Trends</a></li>
    <li><a href="#skills-demand">Skills Demand</a></li>
    <li><a href="#job-survival">Job Survival</a></li>
    <li><a href="#recommendations">Recommendations</a></li>
  </ul>
</nav>

<!-- ══════════════════════════════════════════════════
     SECTION 1 — EXECUTIVE OVERVIEW
═══════════════════════════════════════════════════ -->
<div class="container">
<section class="section" id="executive-overview">
  <div class="section-label">Section 01</div>
  <h2 class="section-title">Executive Overview</h2>
  <p class="section-intro">The following five findings represent the most strategically critical insights from this analysis. Each is directly derived from the 12,343-record dataset spanning 2015–2035.</p>

  <div class="kpi-grid">
    <div class="kpi-card danger">
      <div class="kpi-label">AI Risk (2035 Avg)</div>
      <div class="kpi-value">0.51</div>
      <div class="kpi-sub">Up from 0.30 in 2015</div>
      <div class="kpi-trend up">▲ +70% in 20 years</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Median Salary (2035)</div>
      <div class="kpi-value">$36.8K</div>
      <div class="kpi-sub">Up from $24.2K in 2015</div>
      <div class="kpi-trend up">▲ +52% overall</div>
    </div>
    <div class="kpi-card success">
      <div class="kpi-label">Survival Rate (Class ≥1)</div>
      <div class="kpi-value">89%</div>
      <div class="kpi-sub">In 2015; 84% projected 2035</div>
      <div class="kpi-trend down">▼ Declining trend</div>
    </div>
    <div class="kpi-card warning">
      <div class="kpi-label">High Risk Roles</div>
      <div class="kpi-value">18.6%</div>
      <div class="kpi-sub">Of all records</div>
      <div class="kpi-sub">Business Analyst: 100% High Risk</div>
    </div>
    <div class="kpi-card neutral">
      <div class="kpi-label">Salary–Risk Correlation</div>
      <div class="kpi-value">−0.24</div>
      <div class="kpi-sub">Higher risk = lower pay</div>
      <div class="kpi-sub">Pearson r across all records</div>
    </div>
  </div>

  <div class="exec-findings">
    <div class="exec-finding">
      <div class="exec-icon">🔺</div>
      <div>
        <div class="exec-finding-title">Automation Threat Is Rising Steadily</div>
        <div class="exec-finding-body">The average AI risk score has climbed from 0.30 in 2015 to a projected 0.51 by 2035 — a 70% increase. This is not a sudden disruption but a consistent 20-year pressure that demands proactive response, not reactive management.</div>
      </div>
    </div>
    <div class="exec-finding">
      <div class="exec-icon">⚠️</div>
      <div>
        <div class="exec-finding-title">Two Roles Face Near-Certain Displacement</div>
        <div class="exec-finding-body">Business Analysts (avg risk 0.75, rising to 0.85 by 2035) and Data Analysts (0.65, rising to 0.75) carry 100% and 76% "High Risk" classification rates respectively, and zero probability of "Strong Survival" (Class 2). These roles require urgent reskilling investment.</div>
      </div>
    </div>
    <div class="exec-finding">
      <div class="exec-icon">💰</div>
      <div>
        <div class="exec-finding-title">High-Risk Jobs Pay Significantly Less</div>
        <div class="exec-finding-body">Mean salary for High Risk roles is $23,334 vs. $37,450 for Medium Risk and $36,615 for Low Risk — a 60% penalty. Lower compensation AND higher displacement risk creates a "double jeopardy" for affected workers.</div>
      </div>
    </div>
    <div class="exec-finding">
      <div class="exec-icon">🛡️</div>
      <div>
        <div class="exec-finding-title">AI/ML Skills Offer the Strongest Hedge</div>
        <div class="exec-finding-body">AI Researcher (0% High Risk, 88.9% Strong Survival) and ML Engineer (71.2% Strong Survival) are the most resilient categories. Deep Learning and Python are the top skills in Class 2 (strong survival) roles, appearing in 1,406 and 1,075 records respectively.</div>
      </div>
    </div>
    <div class="exec-finding">
      <div class="exec-icon">🌍</div>
      <div>
        <div class="exec-finding-title">USA Talent Commands a Premium — and Survives Better</div>
        <div class="exec-finding-body">US-based workers earn a median $43,422 (3.5× India's $12,448) and have the highest "Strong Survival" rate at 58%. India shows the lowest survival rate (8.8% Class 2), reflecting role mix concentration in higher-risk categories.</div>
      </div>
    </div>
  </div>

  <div class="callout">
    <strong>Bottom Line for Leadership</strong>
    The data points to a bifurcating labor market: AI-native roles (AI Researcher, ML Engineer, Cybersecurity, DevOps) are expanding in resilience and compensation while analytical/operational roles (Business Analyst, Data Analyst, Software Engineer) face compounding displacement pressure through 2035. The window for proactive workforce transformation is open now — but it is narrowing.
  </div>
</section>

<!-- ══════════════════════════════════════════════════
     SECTION 2 — AUTOMATION RISK LANDSCAPE
═══════════════════════════════════════════════════ -->
<section class="section" id="automation-risk">
  <div class="section-label">Section 02</div>
  <h2 class="section-title">AI Automation Risk Landscape</h2>
  <p class="section-intro">AI risk scores (0–1 scale) measure the probability of significant automation impact on a role. This section examines how risk is distributed across job titles, geographies, and experience levels — and how it is projected to evolve through 2035.</p>

  <div class="chart-grid cols-2">
    <div class="chart-card">
      <div class="chart-title">Average AI Risk Score by Job Title</div>
      <div class="chart-sub">Ranked from highest to lowest automation threat</div>
      <div class="chart-wrap">
        <canvas id="riskByTitle"></canvas>
      </div>
    </div>
    <div class="chart-card">
      <div class="chart-title">AI Risk Score Trend Over Time (2015–2035)</div>
      <div class="chart-sub">Overall mean risk score per year — both historical and projected</div>
      <div class="chart-wrap">
        <canvas id="riskByYear"></canvas>
      </div>
    </div>
  </div>

  <div class="chart-grid cols-2">
    <div class="chart-card">
      <div class="chart-title">AI Risk Category Distribution</div>
      <div class="chart-sub">Share of records by risk category across all years</div>
      <div class="chart-wrap short">
        <canvas id="riskCatDist"></canvas>
      </div>
    </div>
    <div class="chart-card">
      <div class="chart-title">AI Risk Score Trajectory: High-Risk Roles (2015–2035)</div>
      <div class="chart-sub">Five highest-risk job titles showing consistent upward movement</div>
      <div class="chart-wrap">
        <canvas id="riskTrend5"></canvas>
      </div>
    </div>
  </div>

  <div class="callout danger">
